func TestFlagAfterTheReferenceIsHonoured(t *testing.T) {
	requireTooling(t)
	root := repoRoot(t)
	bin := buildBinary(t)

	cond, ok := firingCondition(analyse(t, bin, root, commitWithShadow))
	if !ok {
