	if after.exit != ExitFailOn {
		t.Errorf("flag after the reference: exit = %d, want %d", after.exit, ExitFailOn)
	}
	if before.exit != after.exit {
		t.Errorf("argument order changed the outcome: %d then %d", after.exit, before.exit)
	}
}

